/// <summary>
/// Extension of form MarkupAutoSetup
/// </summary>
[ExtensionOf(formStr(MarkupAutoSetup))]
final class AVAMarkupAutoSetupFrm_Extension
{
}

Method.Source:
/// <summary>
/// Enables columns if MarkupCategory = Pcs/Percent, otherwise disables
/// </summary>
public void avaDateColumnsEnabled()
{
    FormDataSource fds_markupAutoLineLoc = MarkupAutoLine_ds;
    MarkupAutoLine markupAutoLineLoc = fds_markupAutoLineLoc.cursor(); 
    boolean enabled = false;

    if(markupAutoLineLoc.MarkupCategory == MarkupCategory::Pcs
        || markupAutoLineLoc.MarkupCategory == MarkupCategory::Percent)
    {
        enabled = true;
    }

    MarkupAutoLine_AVAFromDate.allowEdit(enabled);
    MarkupAutoLine_AVAToDate.allowEdit(enabled);
}

/// <summary>
/// Makes Columns visible if header module type = Vend, otherwise invisible
/// </summary>
public void avaDateColumnsVisible()
{
    FormDataSource  fds_markupAutoTableLoc  = MarkupAutoTable_ds;
    MarkupAutoTable markupAutoTableLoc      = fds_markupAutoTableLoc.cursor();
    boolean visible = false;

    if (markupAutoTableLoc.ModuleType == MarkupModuleType::Vend)
    {
        visible = true;
    }

    MarkupAutoLine_AVAFromDate.visible(visible);
    MarkupAutoLine_AVAToDate.visible(visible);
}
